from lesson_helpers import *
from bs4 import BeautifulSoup
import re
pops=[]
def add(k,title,body,ids):pops.append('<template data-pop="'+k+'" data-title="'+html.escape(title,quote=True)+'">'+body+ref(*ids)+'</template>')
def concept(k,title,p1,p2,ids):add('g21-'+k,title,'<p>'+p1+'</p><p>'+p2+'</p>',ids)
concept('syndrome','Syndrome et cause ne sont pas synonymes','Le syndrome parkinsonien réunit bradykinésie et rigidité et/ou tremblement de repos. Il décrit un ensemble de signes ; la maladie de Parkinson n’est qu’une des causes.','Une origine médicamenteuse, vasculaire ou postencéphalitique exige une concordance propre. La nomenclature inclut aussi G21.0, syndrome malin, dont le triage est urgent.',('CH-HUG-SEMIO','CH-CIM'))
concept('bradykinesia','Bradykinésie : répétition et amplitude','Observer gestes des doigts, main et pied répétés : vitesse, amplitude et évolution pendant la série. Comparer côtés et gestes fonctionnels ; douleur, faiblesse ou mauvaise compréhension peuvent ralentir autrement.','Le décrément est caractéristique de la maladie de Parkinson, mais son absence dans certaines formes atypiques ne règle pas tout le diagnostic. Une photographie ne mesure pas cette dynamique.',('CH-HUG-SEMIO','EU-DGN-DEF'))
concept('rigidity','Rigidité : mobilisation passive','Patient détendu, mobiliser passivement l’articulation ; rechercher une résistance relativement indépendante de la vitesse. Une manœuvre de renforcement peut aider dans l’examen adapté.','La spasticité dépend davantage de la vitesse et s’accompagne d’autres signes pyramidaux. Une roue dentée sans résistance suffisante ne prouve pas seule une rigidité parkinsonienne.',('CH-HUG-SEMIO','EU-DGN-DEF'))
concept('tremor','Repos, posture et action','Décrire dans quelles conditions apparaît l’oscillation : membre soutenu au repos, posture maintenue ou action. Noter côté, distribution et retentissement.','Le tremblement de repos peut manquer. Asymétrie ou tremblement sous un médicament ne suffisent pas à exclure une cause médicamenteuse ; ils ne prouvent pas non plus une maladie de Parkinson idiopathique.',('CH-HUG-SEMIO','INT-DIP-CLIN'))
concept('d2','D2 postsynaptique et terminaison présynaptique','Un antagoniste peut diminuer la transmission au récepteur striatal sans détruire d’emblée la terminaison nigrostriatale. Ce mécanisme explique un parkinsonisme fonctionnellement induit.','Le transporteur de dopamine exploré par imagerie n’est pas le récepteur D2. Les deux questions ne sont pas interchangeables ; maladie dégénérative et exposition peuvent coexister.',('INT-DIP-MECH','INT-DIP-TEST'))
concept('network','Boucles des noyaux gris','Cortex, striatum, pallidum, noyau sous-thalamique, substance noire et thalamus forment des boucles. Le modèle direct/indirect aide à expliquer une modification de sortie motrice.','Il simplifie un réseau réel plus complexe. La planche normale localise des structures ; aucune flèche causale ni lésion de ce patient n’est déduite de ses couleurs.',('INT-DIP-MECH','IMG-BASAL','IMG-STRIATUM'))
concept('dopamine','Précurseur, récepteur et neurone','La lévodopa fournit un précurseur capable de gagner le cerveau ; le bensérazide limite sa décarboxylation périphérique. Un agoniste agit sur des récepteurs ; un antagoniste peut s’y opposer.','Une cellule pigmentée en histologie ne donne ni taux de dopamine ni nombre de récepteurs occupés. Le mécanisme aide à choisir une question, sans imposer le même médicament à toutes les causes.',('FI-MAD','FI-PARL','INT-DIP-MECH','IMG-HISTO'))
concept('coding','OFS2024 : G21 et ses frontières','Les sous-codes retenus sont.0,.1,.2,.3,.4,.8,.9. G21.0 est le syndrome malin ; G21.1 les autres formes médicamenteuses. Les causes externes peuvent nécessiter un code supplémentaire.','G20, G22* et G23 restent distincts. Un état malin après omission de lévodopa ne devient pas automatiquement G21.0 ; documenter mécanisme et diagnostic, puis coder.',('CH-CIM','CH-CIM-BOUND','FI-MAD'))
concept('iatrogenic','Plusieurs mouvements anormaux sous médicament','Parkinsonisme, akathisie, dystonie aiguë et dyskinésie tardive décrivent des phénomènes différents. Observer le mouvement, le contexte et la chronologie avant d’appliquer une étiquette.','Des signes peuvent coexister. Un anticholinergique utilisé pour certains symptômes peut aggraver une dyskinésie tardive ; en syndrome malin, il peut gêner la perte de chaleur.',('INT-DIP-CLIN','FI-AKI','EU-BAP-THERAPY'))
concept('history','Inclure le médicament caché et la prise omise','Noter noms, indication, forme retard, début, changement et dernière prise réelle. Inclure antiémétiques et traitements reçus ailleurs ; l’ordonnance électronique ne prouve pas la prise effective.','L’omission dopaminergique change le sens de la conduite par rapport au blocage par neuroleptique. La coordination avec prescripteur et pharmacie évite une suppression uniforme de tous les traitements.',('CH-HUG-DIFF','INT-DIP-CLIN','CH-PHEL-CARE','FI-MAD'))
concept('drug-latency','Chronologie : argument, pas preuve isolée','Début après introduction ou hausse d’un médicament soutient une hypothèse. Rechercher néanmoins signes préexistants, autres expositions, pathologies et évolution après changement.','Une amélioration peut prendre semaines ou mois ; persistance, progression ou récidive imposent réévaluation. Aucun délai fixe ne garantit guérison ou irréversibilité chez tout patient.',('INT-DIP-TEST','INT-DIP-MGMT'))
concept('exam','Examen moteur comparatif','Tester gestes répétitifs, tonus passif, tremblement, lever de chaise, marche et demi-tour. Chercher force, réflexes, coordination, oculomotricité et cognition selon contexte.','Le retentissement sur déglutition, chutes et autonomie compte pour le plan de soins. L’examen est répété avec sécurité et ne retarde pas la stabilisation d’une personne instable.',('CH-HUG-SEMIO','CH-HUG-DIFF','CH-PROFILES'))
concept('redflags','Une alerte change le circuit','Dégradation rapide, confusion nouvelle, température anormale, dysautonomie, trouble respiratoire ou déficit brutal demandent évaluation urgente.','Le syndrome malin n’est pas la seule urgence ; infection, accident vasculaire et défaillance métabolique restent à chercher. L’absence d’un signe classique ne suffit pas à rassurer.',('CH-PHEL-CLIN','EU-BAP-CLIN','EU-BAP-THERAPY'))
concept('nms','Syndrome malin : ensemble clinique','Exposition à un antagoniste dopaminergique, altération mentale, rigidité, anomalies thermiques et autonomes orientent. Les présentations peuvent être hétérogènes, notamment sous antipsychotique atypique.','Pas de test spécifique unique. Arrêt causal et support urgent précèdent une éventuelle stratégie spécialisée ; preuves limitées pour les traitements pharmacologiques spécifiques.',('CH-PHEL-CLIN','EU-BAP-CLIN','EU-BAP-THERAPY','EU-BAP-LIMIT'))
concept('catatonia','Catatonie et syndrome malin','Les tableaux peuvent partager rigidité, altération mentale et dysautonomie. La distinction avec catatonie maligne peut être difficile et nécessite toute l’histoire et l’examen.','Ne pas conclure sur une seule valeur de créatine kinase. L’équipe spécialisée choisit les explorations et une stratégie proportionnée à la gravité, en gardant les diagnostics concurrents.',('EU-BAP-CLIN','EU-BAP-THERAPY'))
concept('serotonin','Toxicité sérotoninergique : diagnostic concurrent','Une exposition sérotoninergique et sa chronologie doivent être recherchées dans l’ordonnance complète. Un tableau fébrile et confus ne devient pas automatiquement un syndrome malin.','L’examen neuromusculaire et le contexte aident à distinguer les syndromes ; aucune opposition caricaturale d’un signe isolé ne remplace l’évaluation urgente.',('CH-PHEL-CLIN','EU-BAP-CLIN'))
concept('ck','Créatine kinase : muscle et complications','La hausse peut accompagner une atteinte musculaire et une rhabdomyolyse ; surveiller fonction rénale, potassium et état clinique selon gravité. Les unités et références dépendent du laboratoire.','Le dosage n’est pas spécifique du syndrome malin. Sa valeur isolée, normale ou élevée, ne résout pas à elle seule le diagnostic ni la gravité globale.',('CH-PHEL-CLIN','EU-BAP-THERAPY'))
concept('dat','Transporteur présynaptique en imagerie','Dans une forme surtout postsynaptique, le transporteur peut être préservé. Un déficit peut révéler une atteinte présynaptique, dégénérative ou parfois lésionnelle.','Le résultat n’identifie pas seul une maladie de Parkinson idiopathique et ne distingue pas parfaitement toutes les dégénérescences. Réserver à une incertitude clinique dont la résolution modifierait la conduite.',('INT-DIP-TEST','EU-DGN-IMG','INT-VASC-MRI'))
concept('mri','IRM : une question structurale','Rechercher lésions stratégiques, atteinte vasculaire et autres diagnostics différentiels avec séquences et protocole adaptés. Relier anatomie et temporalité au tableau clinique.','Des hypersignaux de substance blanche fréquents avec l’âge ne suffisent pas à attribuer les symptômes aux vaisseaux. Une image normale ne supprime pas tous les mécanismes médicamenteux.',('EU-DGN-IMG','INT-VASC-MRI','INT-DIP-TEST'))
concept('vascular','Vasculaire : trois profils à distinguer','Le consensus distingue forme postAVC stratégique, forme insidieuse à prédominance marche/axe et forme mixte avec neurodégénérescence. Signes pyramidaux, cognitifs ou urinaires peuvent contribuer à la description.','Le lien clinique-radiologique reste parfois incertain. La réponse dopaminergique est variable ; aucune résistance obligatoire ni traitement antithrombotique automatique ne découle du seul code.',('INT-VASC-CLASS','INT-VASC-MRI','INT-VASC-RESPONSE'))
concept('postenceph','Postencéphalitique ne signifie pas inflammation active','Documenter l’affection antérieure, sa chronologie et le syndrome actuel. Une conséquence résiduelle n’est pas équivalente à une infection ou une auto-immunité persistante.','Une nouvelle altération neurologique exige son propre bilan. Le code G21.3 ne prescrit ni antibiotique, ni corticoïde, ni traitement immunitaire sans diagnostic causal.',('CH-CIM','EU-DGN-DEF','EU-BAP-CLIN'))
concept('withdrawal','Omission dopaminergique : risque de décompensation','L’arrêt brutal de certains antiparkinsoniens peut produire dégradation, rigidité et état ressemblant au syndrome malin. Rechercher jeûne, dysphagie, oubli et interruption lors de transfert.','Une reprise adaptée se discute en urgence, avec formulation et voie possibles. Ne pas assimiler cette situation à une consigne d’arrêt de tous les médicaments dopaminergiques.',('FI-MAD','FI-SYM','CH-PHEL-CARE'))
concept('reduce','Retrait ou substitution : décision coordonnée','Dans une forme médicamenteuse, réévaluer bénéfice et risque du produit responsable. Réduction ou remplacement peut être préférable à un empilement symptomatique.','Le changement antipsychotique ne s’improvise pas : risque de rechute, exposition retard et autres effets comptent. Fixer suivi clinique, autonomie et critères de réévaluation.',('INT-DIP-MGMT','CH-HUG-DIFF'))
concept('akineton','Bipéridène : deux contextes différents','Akineton peut être indiqué dans les troubles extrapyramidaux médicamenteux ; sa tolérance cognitive et anticholinergique limite notamment l’usage chez la personne âgée.','Il n’est pas une réponse universelle à toute rigidité : BAP recommande arrêt des anticholinergiques en syndrome malin. Les formes immédiate et retard ont des plafonds différents.',('FI-AKI','EU-BAP-THERAPY'))
concept('amantadine','Amantadine : dose et intervalle','Symmetrel a une indication adulte comprenant des parkinsonismes médicamenteux. Réduction du produit causal d’abord si possible, puis titration selon FI et tolérance.','La clairance rénale et l’âge modifient fortement la prescription. Confusion, hallucinations ou myoclonies peuvent signaler accumulation ; ne pas traiter automatiquement cela en augmentant la dose.',('FI-SYM','INT-DIP-MGMT'))
concept('levodopa','Madopar : vérifier l’indication','La FI exclut les syndromes d’origine médicamenteuse de son indication. Une forme vasculaire ou mixte peut faire l’objet d’une évaluation spécialisée, sans garantie de réponse.','LIQ125 signifie100mg de lévodopa avec25mg de bensérazide. Ce total commercial ne doit pas être compté comme125mg de lévodopa ; formes retard et dispersible ne sont pas interchangeables au hasard.',('FI-MAD','INT-VASC-RESPONSE'))
concept('bromocriptine','Bromocriptine : indication et interactions','Parlodel est indiqué dans Parkinson idiopathique et postencéphalitique ; usage éventuel en syndrome malin est hospitalier hors indication et repose sur preuves limitées.','Les inhibiteurs puissants ou modérés du CYP3A4 sont contre-indiqués avec ce produit. La titration hebdomadaire de Parkinson ne doit pas être transférée comme protocole d’urgence.',('FI-PARL','EU-BAP-THERAPY','EU-BAP-LIMIT'))
concept('elderly','Âge, cognition et chutes','L’âge ne suffit pas à décider le traitement, mais fragilité, cognition, rétention urinaire, hypotension et charge médicamenteuse modifient la balance. Évaluer marche et sécurité du domicile.','Symmetrel recommande au moins65ans sans pathologie rénale au maximum100mg/j ; l’insuffisance rénale ajoute une autre adaptation. Les anticholinergiques exposent particulièrement à confusion et troubles mnésiques.',('FI-SYM','FI-AKI','CH-HUG-DIFF'))
concept('renal','Ne pas confondre dose et intervalle','La FI Symmetrel donne des intervalles pour100mg selon clairance et sa convention de surface corporelle. Vérifier la mesure utilisée et la tranche avec pharmacie.','À clairance30 dans le tableau,100mg toutes les quarante-huit heures ne signifie pas automatiquement50mg tous les jours. La forme disponible, les bornes du tableau et l’évolution rénale restent à contrôler.',('FI-SYM',))
concept('pregnancy','Grossesse et allaitement : produit par produit','Amantadine et Madopar ont des contre-indications de grossesse dans leurs FI ; les consignes de contraception et d’allaitement sont propres à chaque produit.','Une grossesse sous traitement demande contact médical rapide. Le risque d’arrêt brutal impose d’organiser les modalités, sans conseil d’auto-arrêt ni prolongation automatique. Les indications endocrines de bromocriptine ont un autre cadre.',('FI-SYM','FI-MAD','FI-AKI','FI-PARL'))
concept('rehab','Rééducation et autonomie','Chutes, déglutition, communication, habillement et repas peuvent limiter la vie quotidienne. Mesurer le retentissement avec le patient et les aidants, organiser aides et intervenants selon besoin.','La réduction d’une exposition ne suffit pas toujours à restaurer immédiatement la fonction. Une stratégie de sécurité et de suivi accompagne le traitement causal, sans promettre une guérison à date fixe.',('CH-HUG-SEMIO','CH-HUG-DIFF','INT-DIP-MGMT'))
concept('follow','Suivi : revoir aussi le diagnostic','Documenter signes, autonomie, tolérance et évolution après changement médicamenteux. Une progression persistante peut révéler une maladie sous-jacente ou une autre cause.','Après syndrome malin, une réintroduction antipsychotique n’est pas un simple renouvellement : réévaluer indication, délai après résolution, faible dose et surveillance avec l’équipe.',('INT-DIP-MGMT','EU-BAP-RECHALL','CH-PHEL-RECHALL'))
concept('calculation','Calcul pédagogique : quantité de chaque principe','Trois prises déjà prescrites d’un LIQ125 apportent3×100=300mg de lévodopa et3×25=75mg de bensérazide par jour.375mg est la somme des deux principes, pas la dose de lévodopa.','La dispersion dans25–50mL d’eau n’est pas une solution à concentration fixe autorisant une fraction de verre. Le calcul vérifie une prescription préexistante ; il ne choisit ni indication, ni dose, ni forme.',('FI-MAD',))
concept('prevention','Prévenir l’exposition évitable et l’omission','Conciliation médicamenteuse, indication claire et surveillance limitent les expositions mal reconnues. Lors d’hospitalisation, vérifier les horaires et la capacité de prise des antiparkinsoniens.','Après événement malin, documenter produit et circonstances, informer les équipes et discuter le signalement approprié. Ne pas confondre prévention et arrêt systématique de tout traitement psychiatrique ou dopaminergique.',('CH-PHEL-CARE','EU-BAP-RECHALL','FI-MAD','INT-DIP-MGMT'))
summary=[('Décrire le syndrome, chercher sa cause puis choisir le code.','CH-CIM'),('Les données genevoises historiques n’estiment pas une incidence suisse actuelle.','CH-GENEVA'),('Blocage postsynaptique, perte présynaptique et lésion vasculaire sont des mécanismes différents.','INT-DIP-MECH'),('Urgence d’abord, syndrome ensuite, puis exposition et concordance.','CH-PHEL-CLIN'),('Rechercher aussi médicaments cachés, formes retard et prises omises.','CH-HUG-DIFF'),('Vitesse répétée, tonus passif et conditions du tremblement se testent séparément.','CH-HUG-SEMIO'),('Parkinsonisme, dyskinésie, dystonie et état malin ne sont pas synonymes.','INT-DIP-CLIN'),('Ni symétrie obligatoire ni guérison à délai fixe pour prouver la cause médicamenteuse.','INT-DIP-TEST'),('Un examen doit répondre à une question ; aucun résultat isolé ne remplace la clinique.','EU-DGN-IMG'),('Garder urgence infectieuse, vasculaire et autres diagnostics concurrents.','EU-BAP-CLIN'),('Changer la cause avec le prescripteur, distinguer urgence et traitement chronique.','INT-DIP-MGMT'),('Suivre fonction, tolérance et évolution ; organiser les transferts.','INT-DIP-MGMT'),('Code, mécanisme et choix du produit sont des décisions liées mais différentes.','CH-CIM-BOUND'),('Ne pas extrapoler une indication ou une dose d’un produit à toute rigidité.','FI-MAD')]
path=CH/'G21_a.html';txt=path.read_text()
for i,(essential,sid) in enumerate(summary,1):
 m=re.search(r'(<section\b[^>]*id="g21-'+str(i)+r'"[^>]*>)(.*?)(</section>)',txt,re.S);assert m
 soup=BeautifulSoup(m[2],'html.parser');title=soup.find(['h2','h3']).get_text(' ',strip=True)
 paras=re.findall(r'<p>(.*?)</p>',m[2],re.S)[:2]
 refs=list(dict.fromkeys(a.get_text().split(' — ')[0] for a in soup.select('a[data-reference-source]')))
 add('g21-exp-'+str(i),'Comprendre — '+title,'<p><b>Lecture expliquée.</b> '+essential+'</p>'+''.join('<p>'+p+'</p>' for p in paras),refs)
 add('pareto-g21-'+str(i),'Essentiel — '+title,'<p>'+essential+'</p>'+key('Préciser syndrome, chronologie, mécanisme et décision.'),(sid,))
 entry='<p>'+w('exp-'+str(i),'Comprendre ce point')+' <button class="pareto-btn ui" data-k="pareto-g21-'+str(i)+'">▲ Loi de Pareto — l’essentiel</button></p>'
 txt=txt[:m.end(2)]+entry+txt[m.end(2):]
cases=[('Un médicament derrière les vomissements','Une personne devient lente et raide après introduction d’un antiémétique. Chercher antagonisme dopaminergique, autres expositions et signes antérieurs. Une asymétrie n’exclut pas le rôle du médicament.','Discuter retrait/substitution avec le prescripteur, surveiller autonomie et évolution ; ne pas ajouter automatiquement Madopar dont la FI exclut les formes médicamenteuses.',('INT-DIP-CLIN','INT-DIP-MGMT','FI-MAD')),('Rigidité et confusion après neuroleptique','Un patient confus se rigidifie et présente une température anormale après modification d’un neuroleptique. Rechercher syndrome malin, diagnostics concurrents et complications.','Évaluation urgente, arrêt du produit causal et des anticholinergiques, support individualisé ; ne pas attendre une créatine kinase particulière pour appeler.',('EU-BAP-CLIN','EU-BAP-THERAPY','CH-PHEL-CARE')),('Trouble de marche et hypersignaux','Une personne âgée marche difficilement et son imagerie montre des lésions de substance blanche. Cela ne démontre pas seul une causalité vasculaire.','Décrire syndrome, chronologie et signes associés ; discuter profil insidieux, lésion stratégique ou forme mixte. La réponse à la lévodopa n’est pas uniforme.',('INT-VASC-CLASS','INT-VASC-MRI','INT-VASC-RESPONSE')),('Prises omises pendant un jeûne','Un traitement dopaminergique habituel est omis pendant un jeûne hospitalier ; la personne développe rigidité, confusion et dysautonomie. Une décompensation de sevrage est possible.','Évaluation urgente et discussion de reprise avec voie/formulation adaptées ; ne pas coder automatiquement comme exposition neuroleptique ni arrêter tous les dopaminergiques.',('FI-MAD','FI-SYM','CH-PHEL-CARE','CH-CIM'))]
for i,(title,p1,p2,refs) in enumerate(cases,1):add('g21-cas-'+str(i),'Cas '+str(i)+' — '+title,'<p><b>Exercice fictif original.</b></p><p>'+p1+'</p><p>'+p2+'</p>',refs)
quiz=[('Le tremblement de repos est-il indispensable au syndrome parkinsonien ?','Non, une bradykinésie avec rigidité peut suffire.','Oui, il doit toujours être présent.','Le syndrome associe bradykinésie à rigidité et/ou tremblement de repos.','CH-HUG-SEMIO'),('Une rigidité confuse et fébrile après neuroleptique peut-elle attendre le suivi habituel ?','Non, une évaluation urgente est nécessaire.','Oui, si aucun tremblement n’est observé.','Rechercher syndrome malin et autres urgences ; le tremblement ne décide pas du triage.','EU-BAP-THERAPY'),('Les hypersignaux de substance blanche prouvent-ils seuls un parkinsonisme vasculaire ?','Non, il faut une concordance clinique et chronologique.','Oui, toute lésion de substance blanche suffit.','Les lésions peuvent coexister sans expliquer tout le tableau ; formes mixtes possibles.','INT-VASC-MRI'),('Trois Madopar LIQ125 contiennent combien de lévodopa ?','Trois cents milligrammes, avec soixante-quinze de bensérazide.','Trois cent soixante-quinze milligrammes de lévodopa.','Le nom125 additionne100mg de lévodopa et25mg de bensérazide par unité.','FI-MAD')]
q=''.join('<div class="quiz ui"><p>'+question+'</p><button data-ok="1">'+yes+'</button><button data-ok="0">'+no+'</button><p class="fb" hidden>'+ex+'</p></div>'+ref(sid) for question,yes,no,ex,sid in quiz)
txt=txt.replace('</div></div>',sec('entrainement','S’entraîner : quatre décisions et quatre cas',q+'<p>'+' '.join(w('cas-'+str(i),'Cas '+str(i)) for i in range(1,5))+'</p>',('CH-PROFILES','CH-MEBEKO'))+'</div></div>',1);path.write_text(txt)
save('pop1','\n'.join(pops[:34]));save('pop2','\n'.join(pops[34:]));assert len(pops)==66
print('G21 :66fenêtres,14Pareto,4quiz et4cas.')
